/**
 * dialogues.ts — Catalogue de dialogues (porté depuis l'app web).
 *
 * Mêmes identifiants et mêmes contenus bilingues que xiaolearn_app :
 * un dialogue écouté ici est le même que sur le web.
 *
 * NE PAS ÉDITER À LA MAIN — recopier depuis xiaolearn_app/src/data/.
 */

export interface DialogueLine {
  speaker: string;
  hanzi: string;
  pinyin: string;
  translationFr: string;
  translationEn: string;
  note?: string;
  noteEn?: string;
  audioUrl?: string;
}

/**
 * Question de compréhension à choix multiples.
 *
 * `correct` indexe les deux tableaux de choix à la fois : les traductions
 * doivent donc rester alignées position par position. Les bonnes réponses
 * sont volontairement réparties entre les positions — un lecteur qui
 * enchaîne les dialogues ne doit pas pouvoir deviner « c'est toujours la
 * deuxième ».
 */
export interface DialogueQuizQuestion {
  questionFr: string;
  questionEn: string;
  choicesFr: string[];
  choicesEn: string[];
  correct: number;
  /** Pourquoi cette réponse — affiché après validation, jamais avant. */
  explanationFr?: string;
  explanationEn?: string;
}

export interface Dialogue {
  id: string;
  title: string;
  titleEn: string;
  context: string;
  contextEn: string;
  lines: DialogueLine[];
  vocab?: string[];
  comprehension?: {
    questionFr: string;
    questionEn: string;
    answerFr: string;
    answerEn: string;
  };
  /** Exercices de compréhension — chaque question ne porte que sur le texte. */
  quiz?: DialogueQuizQuestion[];
}

export type DialogueLevel = 'a1' | 'a2' | 'b1.1' | 'b1.2' | 'b2.1' | 'b2.2' | 'c1.1' | 'c1.2' | 'c2.1' | 'c2.2';

export interface DialogueEntry {
  cecrLevel: DialogueLevel;
  theme: string;
  themeEn: string;
  dialogue: Dialogue;
}

/** Ordre et libellés d'affichage des niveaux. */
export const DIALOGUE_LEVELS: DialogueLevel[] = ['a1', 'a2', 'b1.1', 'b1.2', 'b2.1', 'b2.2'];
export const LEVEL_LABEL: Record<DialogueLevel, string> = {
  a1: 'A1', a2: 'A2', 'b1.1': 'B1.1', 'b1.2': 'B1.2',
  'b2.1': 'B2.1', 'b2.2': 'B2.2', 'c1.1': 'C1.1', 'c1.2': 'C1.2',
  'c2.1': 'C2.1', 'c2.2': 'C2.2',
};

/** Émoji par thème — repris de la maquette web. */
