          choicesEn: ["The soup is cold and the service is far too slow.","The dish is cold and there's a mistake on the bill.","The soup is too salty and he was served chicken.","The soup is cold and he was served chicken instead of beef."],
          correct: 3,
          explanationFr: "«这个汤已经凉了，而且我点的是牛肉，不是鸡肉» : soupe froide et erreur de viande.",
          explanationEn: "这个汤已经凉了，而且我点的是牛肉，不是鸡肉: cold soup plus the wrong meat.",
