          choicesFr: ["Parce que les prix ont cessé de monter et que l'achat n'est plus rentable","Parce qu'au prix actuel il lui faudrait environ dix ans pour réunir l'apport","Parce qu'elle envisage de partir travailler dans une autre ville","Parce que son bail actuel court encore sur cinq années"],
          choicesEn: ["Because prices have stopped rising and buying no longer pays","Because at today's prices she'd need about ten years to save the deposit","Because she is considering moving to another city for work","Because her current lease still runs for five years"],
