          choicesFr: ["Il admet que la propriété demeure le meilleur placement de long terme","Il reconnaît qu'un loyer augmente moins vite qu'une mensualité de crédit","Il concède que la souplesse compte peu avant trente-cinq ans","Il reconnaît que les contraintes institutionnelles existent et que le cadre est perfectible"],
          choicesEn: ["He admits ownership remains the best long-term investment","He accepts that rent rises more slowly than a loan repayment","He concedes flexibility matters little before thirty-five","He acknowledges the institutional constraints are real and the framework improvable"],
