          choicesFr: ["Dans le montant total dépensé sur vingt ans","Dans l'accès des enfants à l'école du quartier","Dans la souplesse : un loyer peut être réduit, pas une mensualité","Dans la durée des baux, plus longue à l'étranger que chez eux"],
          choicesEn: ["In the total amount spent over twenty years","In children's access to the local school","In flexibility: rent can be reduced, a loan repayment cannot","In lease length, longer abroad than at home"],
